code_sketch:
let fib = sequence(state: (0, 1)) { (s: inout (Int, Int)) in
    defer { s = (s.1, s.0 + s.1) }
    return s.0                       // produced per iteration
}

for n in fib.lazy.filter({ $0.isMultiple(of: 2) }).prefix(10) {
    print(n)                         // pulled on demand, then stops
}

